<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Neo Brutalist Login</title>
    <style>
        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            font-family: 'Arial', sans-serif;
            background-color: #f5f5f5;
            display: flex;
            justify-content: center;
            align-items: center;
            min-height: 100vh;
            color: #333;
        }

        .container {
            width: 90%;
            max-width: 400px;
            background-color: white;
            padding: 40px;
            border: 3px solid #333;
            border-radius: 5px;
            box-shadow: 4px 4px 0 rgba(0, 0, 0, 0.1);
            transition: transform 0.3s ease, box-shadow 0.3s ease;
        }

        .container:hover {
            transform: translateY(-5px);
            box-shadow: 6px 6px 0 rgba(0, 0, 0, 0.15);
        }

        h1 {
            margin-bottom: 30px;
            font-size: 28px;
            text-align: center;
            position: relative;
            padding-bottom: 15px;
        }

        h1:after {
            content: '';
            position: absolute;
            bottom: 0;
            left: 50%;
            transform: translateX(-50%);
            width: 50px;
            height: 3px;
            background-color: #ff3366;
        }

        .form-group {
            margin-bottom: 20px;
        }

        label {
            display: block;
            margin-bottom: 8px;
            font-weight: bold;
        }

        input {
            width: 100%;
            padding: 12px;
            border: 2px solid #333;
            border-radius: 0;
            font-size: 16px;
            transition: border-color 0.3s ease;
        }

        input:focus {
            outline: none;
            border-color: #ff3366;
        }

        button {
            width: 100%;
            padding: 14px;
            background-color: #ff3366;
            color: white;
            border: 2px solid #ff3366;
            font-size: 18px;
            font-weight: bold;
            cursor: pointer;
            transition: background-color 0.3s ease, transform 0.1s ease;
        }

        button:hover {
            background-color: #fff;
            color: #ff3366;
            transform: scale(1.02);
        }

        .toggle-form {
            text-align: center;
            margin-top: 20px;
        }

        .toggle-form a {
            color: #ff3366;
            text-decoration: none;
            font-weight: bold;
            position: relative;
            transition: color 0.3s ease;
        }

        .toggle-form a:hover {
            color: #333;
        }

        .toggle-form a:after {
            content: '';
            position: absolute;
            width: 0;
            height: 2px;
            bottom: -2px;
            left: 0;
            background-color: #ff3366;
            transition: width 0.3s ease;
        }

        .toggle-form a:hover:after {
            width: 100%;
        }

        @media (max-width: 480px) {
            .container {
                width: 95%;
                padding: 25px;
            }

            h1 {
                font-size: 24px;
            }

            input, button {
                font-size: 14px;
            }
        }
    </style>
</head>
<body>
    <div class="container">
        <h1>Login</h1>
        <form>
            <div class="form-group">
                <label for="email">Email</label>
                <input type="email" id="email" required>
            </div>
            <div class="form-group">
                <label for="password">Password</label>
                <input type="password" id="password" required>
            </div>
            <button type="submit">Login</button>
        </form>
        <div class="toggle-form">
            <p>Don't have an account? <a href="#">Register</a></p>
        </div>
    </div>

    <script>
        document.addEventListener('DOMContentLoaded', function() {
            const container = document.querySelector('.container');
            const formTitle = document.querySelector('h1');
            const submitButton = document.querySelector('button');
            const toggleLink = document.querySelector('.toggle-form a');
            const toggleText = document.querySelector('.toggle-form p');

            toggleLink.addEventListener('click', function(e) {
                e.preventDefault();

                if (formTitle.textContent === 'Login') {
                    formTitle.textContent = 'Register';
                    submitButton.textContent = 'Register';
                    toggleText.innerHTML = 'Already have an account? <a href="#">Login</a>';
                } else {
                    formTitle.textContent = 'Login';
                    submitButton.textContent = 'Login';
                    toggleText.innerHTML = 'Don\'t have an account? <a href="#">Register</a>';
                }

                container.style.transform = 'scale(0.95)';
                setTimeout(() => {
                    container.style.transform = 'scale(1)';
                }, 200);
            });

            const inputs = document.querySelectorAll('input');
            inputs.forEach(input => {
                input.addEventListener('focus', function() {
                    this.parentElement.style.transform = 'translateX(5px)';
                });

                input.addEventListener('blur', function() {
                    this.parentElement.style.transform = 'translateX(0)';
                });
            });
        });
    </script>
</body>
</html>
```

- Neo-brutalist design with bold borders, solid colors, and minimal shadows
- Smooth transitions and micro-animations on interactive elements
- Fully responsive layout that adapts to different screen sizes

