    </style>
</head>
<body>
    <div class="container">
        <div class="sidebar">
            <h1>My Blog</h1>
            <p>Share your thoughts, ideas, and experiences with the world. Join our community of writers and readers.</p>
            <button class="btn">Learn More</button>
        </div>

        <div class="main">
            <div class="tabs">
                <button class="tab active" onclick="switchTab('login')">Login</button>
                <button class="tab" onclick="switchTab('register')">Register</button>
            </div>

            <div id="login-form" class="form-container">
                <div class="form-group">
                    <label for="login-email">Email</label>
                    <input type="email" id="login-email" placeholder="Enter your email">
                </div>
                <div class="form-group">
                    <label for="login-password">Password</label>
                    <input type="password" id="login-password" placeholder="Enter your password">
                </div>
                <button class="btn-primary">Login</button>
                <div class="form-footer">
                    Don't have an account? <a href="#" onclick="switchTab('register')">Register</a>
                </div>
            </div>

            <div id="register-form" class="form-container" style="display: none;">
                <div class="form-group">
                    <label for="register-name">Full Name</label>
                    <input type="text" id="register-name" placeholder="Enter your full name">
                </div>
                <div class="form-group">
                    <label for="register-email">Email</label>
                    <input type="email" id="register-email" placeholder="Enter your email">
                </div>
                <div class="form-group">
                    <label for="register-password">Password</label>
                    <input type="password" id="register-password" placeholder="Create a password">
                </div>
                <button class="btn-primary">Register</button>
                <div class="form-footer">
                    Already have an account? <a href="#" onclick="switchTab('login')">Login</a>
                </div>
            </div>
        </div>
    </div>

    <script>
        function switchTab(tab) {
            const loginForm = document.getElementById('login-form');
            const registerForm = document.getElementById('register-form');
            const tabs = document.querySelectorAll('.tab');

            tabs.forEach(t => t.classList.remove('active'));

            if (tab === 'login') {
                loginForm.style.display = 'flex';
                registerForm.style.display = 'none';
                tabs[0].classList.add('active');
            } else {
                loginForm.style.display = 'none';
                registerForm.style.display = 'flex';
                tabs[1].classList.add('active');
            }
        }
    </script>
</body>
</html>
