                    <span class="item-price">$1,800</span>
                </div>

                <div class="item">
                    <span class="item-name">SEO Optimization</span>
                    <span class="item-price">$900</span>
                </div>

                <div class="item">
                    <span class="item-name">Content Strategy</span>
                    <span class="item-price">$1,200</span>
                </div>

                <div class="total">
                    <span>Total</span>
                    <span>$6,400</span>
                </div>
            </div>

            <div class="card">
                <div class="card-header">
                    <h2 class="card-title">Payment Details</h2>
                </div>

                <form>
                    <div class="form-group">
                        <label for="card-number">Card Number</label>
                        <input type="text" id="card-number" placeholder="1234 5678 9012 3456">
                    </div>

                    <div class="form-group">
                        <label for="expiry">Expiry Date</label>
                        <input type="text" id="expiry" placeholder="MM/YY">
                    </div>

                    <div class="form-group">
                        <label for="cvv">CVV</label>
                        <input type="text" id="cvv" placeholder="123">
                    </div>

                    <div class="form-group">
                        <label for="name">Cardholder Name</label>
                        <input type="text" id="name" placeholder="John Doe">
                    </div>

                    <div class="checkbox-group">
                        <input type="checkbox" id="save-card">
                        <label for="save-card">Save card for future purchases</label>
                    </div>

